def process_sig_rx(self, dict_sig=None):
    """
    Process signals coming from the navigation toolbar and from sig_rx
    """
    logger.debug("PROCESS_SIG_RX:\n%s \n\tneeds_calc = %s, visible = %s",
                 pprint_log(dict_sig), self.needs_calc, self.isVisible())

    if dict_sig['id'] == id(self):
        logger.warning("Stopped infinite loop:\n%s", pprint_log(dict_sig))
        return

    if self.isVisible():
        if 'data_changed' in dict_sig or self.needs_calc\
                or ('mpl_toolbar' in dict_sig and dict_sig['mpl_toolbar'] == 'home'):
            self.draw()
            self.needs_calc = False
            self.needs_draw = False
        elif 'view_changed' in dict_sig or self.needs_draw:
            self.update_view()
            self.needs_draw = False
        elif 'mpl_toolbar' in dict_sig and dict_sig['mpl_toolbar'] == 'ui_level':
            self.frmControls.setVisible(self.mplwidget.mplToolbar.a_ui_level == 0)

    else:
        if 'data_changed' in dict_sig:
            self.needs_calc = True
        elif 'view_changed' in dict_sig:
            self.needs_draw = True

def process_sig_rx(self, dict_sig=None):
    """
    Process signals coming from the navigation toolbar and from ``sig_rx``
    """
    logger.debug("Processing %s | data_changed = %s, visible = %s",
                 dict_sig, self.data_changed, self.isVisible())
    if self.isVisible():
        if 'data_changed' in dict_sig or self.data_changed\
                or ('mpl_toolbar' in dict_sig and dict_sig['mpl_toolbar'] == 'home'):
            self.draw()
            self.data_changed = False
        elif 'mpl_toolbar' in dict_sig and dict_sig['mpl_toolbar'] == 'ui_level':
            self.frmControls.setVisible(self.mplwidget.mplToolbar.a_ui_level == 0)

    else:
        if 'data_changed' in dict_sig:
            self.data_changed = True
